const inputStr = omniloginRefData('variables', 'accountListStr') || '';
const sep = omniloginRefData('variables', 'sep') || '|';
const index = omniloginRefData('runIndex') || 0;

const accountList = inputStr.split("\n").filter(x => !!x).map(line => {
  const [username, password,fa] = line.split(sep);

  return {username, password,fa};
});

const account = accountList[index];
if (!account) {
  throw new Error("Missing account");
}
omniloginSetVariable('account', account)
